window.addEventListener('load',function(){
 const button=document.getElementById('btn-recovery-compensation'),status=document.getElementById('recovery-compensation-status'),modal=document.getElementById('modal-recovery-compensation');let activeGift=null;
 const showReceived=()=>{button.disabled=true;button.textContent='受け取り済み';status.textContent='このギフトは1回限りです。';};
 function open(code){const gift=KanjiGiftCodes.get(code);if(!gift){document.getElementById('recovery-code-status').textContent='無効なギフトコードです。以前の補填コードは終了しました。';return;}activeGift=gift;button.disabled=false;button.textContent=KanjiGiftCodes.describe(gift)+'を受け取る';document.getElementById('recovery-gift-description').textContent=KanjiGiftCodes.describe(gift)+'を受け取れます。1回限り。';status.textContent='';try{if(KanjiGiftCodes.received(gameState,localStorage,gift))showReceived();}catch{}modal.classList.remove('hidden');if(typeof pausePlayerOverlay==='function')pausePlayerOverlay();switchTab('rank');document.getElementById(button.disabled?'btn-recovery-close':'btn-recovery-compensation').focus({preventScroll:true});}
 button.onclick=()=>{if(!activeGift)return;button.disabled=true;try{if(!saveStore)throw Error('storage');const next=KanjiGiftCodes.claim(gameState,saveStore,localStorage,activeGift.code);if(!next){showReceived();return;}gameState=next;saveRecoveryBlocked=false;saveWarningShown=false;saveState(true);showReceived();status.textContent=KanjiGiftCodes.describe(activeGift)+'を追加して保存しました。';document.getElementById('recovery-code-status').textContent=status.textContent;close();}catch{button.disabled=false;status.textContent='保存できなかったため、受け取りは未完了です。Safariの通常タブで開き直してください。';}};
 function close(){modal.classList.add('hidden');if(typeof resumePlayerEngine==='function')resumePlayerEngine();}
 document.getElementById('btn-recovery-close').onclick=close;modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}});
 document.getElementById('recovery-code-form').onsubmit=e=>{e.preventDefault();document.getElementById('recovery-code-status').textContent='';open(document.getElementById('recovery-code-input').value);};
 const code=new URLSearchParams(location.search).get('gift');if(code)open(code);
});
